using MeiErp.Platform.Reporting;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;
namespace MeiErp.Modules.Auto;
public static class AutoReports
{
 public static IServiceCollection AddAutoReports(this IServiceCollection s){s.AddSingleton<ReportDefinition>(sp=>new(){Key="auto.maintenance-cost",Name="Maintenance Cost by Vehicle",Description="Service record count, total running cost, and next due date.",ModuleKey=AutoModule.Key,Group="Fleet",Permission=AutoModule.ReportsView,Uses=ReportFilters.None,Run=async(r,ct)=>{using var scope=sp.CreateScope();var rows=await scope.ServiceProvider.GetRequiredService<AutoDbContext>().Vehicles.AsNoTracking().Include(x=>x.Services).OrderBy(x=>x.Registration).ToListAsync(ct);return new(){Columns=[new("vehicle","Vehicle"),new("status","Status",ReportValueKind.Status),new("records","Records",ReportValueKind.Number),new("cost","Total cost",ReportValueKind.Money),new("next","Next due",ReportValueKind.Date)],Rows=[..rows.Select(x=>new ReportRow(new Dictionary<string,object?>{{"vehicle",$"{x.Registration} — {x.Make} {x.Model}"},{"status",x.Status},{"records",x.Services.Count},{"cost",x.Services.Sum(y=>y.Cost)},{"next",x.Services.Where(y=>y.NextDueDate!=null).OrderBy(y=>y.NextDueDate).FirstOrDefault()?.NextDueDate}},"/auto/vehicles"))],Totals=[new("cost",rows.Sum(x=>x.Services.Sum(y=>y.Cost)))]};}});return s;}
}
